def block_attention_mask(valid, block_start):
    if not valid or not valid[0]:
        raise ValueError("nonempty batch and sequence required")
    n = len(valid[0])
    if len(block_start) != n or any(len(row) != n for row in valid):
        raise ValueError("inconsistent lengths")
    if any(type(value) is not bool for row in valid for value in row):
        raise ValueError("valid entries must be bool")
    if any(type(value) is not bool for value in block_start):
        raise ValueError("block_start entries must be bool")
    groups, total = [], 0
    for start in block_start:
        total += int(start)
        groups.append(total)
    return [[[bool(row[i] and row[j] and groups[j] <= groups[i])
              for j in range(n)] for i in range(n)] for row in valid]
